mapper.select:
SELECT FROM geo_region WHERE status = 1 AND path LIKE CONCAT(#{pathPrefix}, '%')
AND level <= #{maxLevel}
ORDER BY level ASC, sort ASC, id ASC LIMIT #{maxRows}

(
    SELECT 
    FROM geo_region
    WHERE status = 1
      AND country_code = #{countryCode}
      AND name LIKE CONCAT(#{keyword}, '%')

      AND level = #{level}

    ORDER BY level ASC, sort ASC, id ASC
    LIMIT #{limit}
)
UNION
(
    SELECT 
    FROM geo_region
    WHERE status = 1
      AND country_code = #{countryCode}
      AND name_en LIKE CONCAT(#{keyword}, '%')

      AND level = #{level}

    ORDER BY level ASC, sort ASC, id ASC
    LIMIT #{limit}
)
UNION
(
    SELECT 
    FROM geo_region
    WHERE status = 1
      AND country_code = #{countryCode}
      AND name_ch LIKE CONCAT(#{keyword}, '%')

      AND level = #{level}

    ORDER BY level ASC, sort ASC, id ASC
    LIMIT #{limit}
)
ORDER BY level ASC, sort ASC, id ASC
LIMIT #{limit}

SELECT parent_id AS parentId, COUNT(*) AS cnt FROM geo_region WHERE status = 1 AND parent_id IN
#{id}
GROUP BY parent_id
